SELECT SUBSTR(name, 1, 3), SUBSTRING(name FROM 2 FOR 3), SUBSTRING(name, 1, 2, OCTETS), SUBSTRING(name FROM 1 FOR 2 USING CODEUNITS32) FROM t;
SELECT TRIM(name), TRIM(LEADING '0' FROM code), TRIM(TRAILING FROM name), TRIM(BOTH ' ' FROM name), LTRIM(a), RTRIM(b) FROM t;
SELECT POSITION('x' IN name), POSITION('x', name, OCTETS), LOCATE('a', name), LOCATE_IN_STRING(name, 'a', 1, 2), INSTR(name, 'b') FROM t;
SELECT EXTRACT(YEAR FROM hiredate), EXTRACT(MONTH FROM ts), EXTRACT(DAY FROM d) FROM t;
SELECT YEAR(d), MONTH(d), DAY(d), HOUR(ts), MINUTE(ts), SECOND(ts), MICROSECOND(ts), DAYOFWEEK(d), WEEK(d), QUARTER(d) FROM t;
SELECT DATE(ts), TIME(ts), TIMESTAMP(d, t), TIMESTAMP_FORMAT('2024-01-01', 'YYYY-MM-DD'), VARCHAR_FORMAT(ts, 'YYYY-MM-DD HH24:MI:SS'), TO_CHAR(ts, 'YYYY'), TO_DATE('2024', 'YYYY') FROM t;
SELECT CHAR(d, ISO), CHAR(amount), VARCHAR(name, 20), INTEGER(x), INT(x), BIGINT(x), SMALLINT(x), DECIMAL(x, 10, 2), DEC(x, 5), DOUBLE(x), FLOAT(x), REAL(x), DECFLOAT(x) FROM t;
SELECT LEFT(name, 3), RIGHT(name, 2), INSERT(name, 1, 2, 'xx'), REPLACE(name, 'a', 'b'), CONCAT(a, b), UPPER(a), LOWER(b), UCASE(c), LCASE(d), LENGTH(a), CHARACTER_LENGTH(a USING OCTETS) FROM t;
SELECT ABS(x), MOD(x, 3), ROUND(x, 2), TRUNC(x, 1), TRUNCATE(x, 0), CEIL(x), FLOOR(x), POWER(x, 2), SQRT(x), SIGN(x), RAND() FROM t;
SELECT HEX(a), DIGITS(b), TRANSLATE(c, 'abc', 'xyz'), LPAD(d, 10, '0'), RPAD(e, 5), REPEAT('-', 20), SPACE(3), STRIP(f), GENERATE_UNIQUE(), HASH(g, 2) FROM t;
SELECT XMLSERIALIZE(XMLAGG(XMLELEMENT(NAME "e", name) ORDER BY name) AS CLOB(1M)) FROM t;
SELECT XMLELEMENT(NAME "emp", XMLATTRIBUTES(empno AS "id", lastname), XMLFOREST(firstnme AS "first", salary)) FROM employee;
SELECT XMLCAST(XMLQUERY('$d/a/text()' PASSING doc AS "d") AS VARCHAR(100)) FROM xmltab;
SELECT JSON_VALUE(doc, '$.name' RETURNING VARCHAR(50)), JSON_OBJECT(KEY 'id' VALUE id, KEY 'name' VALUE name), BSON_TO_JSON(b) FROM jtab;
SELECT SYSPROC.ENV_GET_INST_INFO(), app.my_udf(1, 'a'), "quoted"."func"(2), myfunc() FROM sysibm.sysdummy1;
SELECT DBPARTITIONNUM(a), DATAPARTITIONNUM(a), MON_GET_APPLICATION_HANDLE(), TYPE_NAME(x) FROM t;
SELECT ADD_MONTHS(d, 1), LAST_DAY(d), NEXT_DAY(d, 'MON'), MONTHS_BETWEEN(d1, d2), DAYS_BETWEEN(d1, d2), ROUND_TIMESTAMP(ts, 'HH'), TRUNC_TIMESTAMP(ts, 'MM') FROM t;
SELECT GREATEST(a, b, c), LEAST(a, b), NVL2(a, b, c), IFNULL(a, 0), RAISE_ERROR('70001', 'bad') FROM t;
SELECT f(p1 => 1, p2 => 'x') FROM sysibm.sysdummy1;
SELECT TRY_CAST(a AS INTEGER), XMLCAST(b AS VARCHAR(10)) FROM t;
